// Validate what Claude extracted. The model transcribes; this node decides.
// Every check runs in code here, on purpose - the point of the workflow is
// that an invoice is not trusted just because an AI read it confidently.

const REVIEW_THRESHOLD = 5000;   // currency units - see README on the single-currency assumption
const TOLERANCE = 0.02;          // absolute, to absorb rounding on tax lines

function firstText(content) {
  if (!Array.isArray(content)) return "";
  const block = content.find((c) => c && c.type === "text");
  return block && typeof block.text === "string" ? block.text : "";
}

function extractJson(text) {
  if (!text) return null;
  let t = String(text).trim();
  t = t.replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
  const start = t.indexOf("{");
  const end = t.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) return null;
  try {
    return JSON.parse(t.slice(start, end + 1));
  } catch (err) {
    return null;
  }
}

function num(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ""));
  return Number.isFinite(n) ? n : null;
}

const sources = $("Webhook: Invoice Intake").all();
const incoming = $input.all();
const results = [];

for (let i = 0; i < incoming.length; i++) {
  const src = sources[Math.min(i, sources.length - 1)];
  const source_file = (src && src.json && src.json.query && src.json.query.source_file) || "unknown";

  const parsed = extractJson(firstText(incoming[i].json.content));

  // Could not read the model output at all -> a human looks at it.
  if (!parsed) {
    results.push({
      json: {
        source_file,
        vendor_name: null, invoice_number: null, invoice_date: null, due_date: null,
        currency: null, subtotal: null, tax_amount: null, total_amount: null,
        line_items: [], line_items_json: "[]", confidence_notes: "",
        status: "needs_review",
        flag_reason: "extraction_unreadable: model response was not valid JSON",
      },
      pairedItem: { item: i },
    });
    continue;
  }

  const vendor_name = parsed.vendor_name || null;
  const invoice_date = parsed.invoice_date || null;
  const subtotal = num(parsed.subtotal);
  const tax_amount = num(parsed.tax_amount);
  const total_amount = num(parsed.total_amount);
  const line_items = Array.isArray(parsed.line_items) ? parsed.line_items : [];
  const confidence_notes = String(parsed.confidence_notes || "").trim();

  const flags = [];

  // 1. Required fields must be present.
  const missing = [];
  if (!vendor_name) missing.push("vendor_name");
  if (!invoice_date) missing.push("invoice_date");
  if (total_amount === null) missing.push("total_amount");
  if (missing.length) flags.push("missing_fields: " + missing.join(", "));

  // 2. Line items should reconcile to the subtotal.
  if (line_items.length && subtotal !== null) {
    const sum = line_items.reduce((acc, li) => {
      const amt = num(li && li.amount);
      if (amt !== null) return acc + amt;
      const q = num(li && li.quantity);
      const p = num(li && li.unit_price);
      return q !== null && p !== null ? acc + q * p : acc;
    }, 0);
    const diff = Math.abs(sum - subtotal);
    if (diff > TOLERANCE) {
      flags.push(
        "line_items_do_not_match_subtotal: items sum to " + sum.toFixed(2) +
        " but subtotal reads " + subtotal.toFixed(2) + " (off by " + diff.toFixed(2) + ")"
      );
    }
  }

  // 3. Subtotal + tax should reconcile to the total.
  if (subtotal !== null && tax_amount !== null && total_amount !== null) {
    const diff = Math.abs(subtotal + tax_amount - total_amount);
    if (diff > TOLERANCE) {
      flags.push(
        "totals_do_not_reconcile: " + subtotal.toFixed(2) + " + " + tax_amount.toFixed(2) +
        " = " + (subtotal + tax_amount).toFixed(2) + " but total reads " + total_amount.toFixed(2)
      );
    }
  }

  // 4. Large amounts get a human look before they are booked. Not an error.
  if (total_amount !== null && total_amount > REVIEW_THRESHOLD) {
    flags.push("above_review_threshold: " + total_amount.toFixed(2) + " exceeds " + REVIEW_THRESHOLD);
  }

  // 5. The model told us it was unsure.
  if (confidence_notes) flags.push("model_uncertain: " + confidence_notes);

  results.push({
    json: {
      source_file,
      vendor_name,
      invoice_number: parsed.invoice_number || null,
      invoice_date,
      due_date: parsed.due_date || null,
      currency: parsed.currency || null,
      subtotal,
      tax_amount,
      total_amount,
      line_items,
      line_items_json: JSON.stringify(line_items),
      confidence_notes,
      status: flags.length ? "needs_review" : "auto_processed",
      flag_reason: flags.join(" | "),
    },
    pairedItem: { item: i },
  });
}

return results;
